import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Subtitulos, Textura, Profundidad, Brillo, Paso, Recorrido, seguir, Chip, Regla, Ondas, golpe, h, clamp, interpolate, Easing, FONT} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const FOTOS = en('fotos'), TU = en('Tu'), ESPEJO = en('espejo'), VOLTEA = en('voltea'), LUNAR = en('lunar'), IZQ = en('izquierda'), DER = en('derecha');
const DOS = en('dos'), ALTO = en('alto'), SONRISA = en('sonrisa'), LLEVAS = en('Llevas'), CEREBRO = en('cerebro'), Y1977 = en('1977'), WISC = en('Wisconsin');
const PRUEBA = en('prueba'), TOMARON = en('Tomaron'), IMPRIM = en('imprimieron'), VECES = en('veces'), NORMAL1 = en('Normal'), VOLT1 = en('volteada');
const ELIG1 = en('eligieron'), SUS = en('Sus'), NORMAL2 = en('normal', 2), RARA = en('rara'), DEMAS = en('demás', 2), MAL = en('mal'), DERECHO = en('derecho');
const BORRAR = en('borrar'), BORRA = en('borra'), DALE = en('Dale');

const LIMA = '#E7FF00', CELESTE = '#BFE3F2', CALIDO = '#F4D7B5';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;

// Cara de mujer joven con rizos y un lunar en la mejilla izquierda (de quien mira). Protagonista: el lunar.
const Cara: React.FC<{x: number; y: number; sc?: number; flip?: boolean; squish?: number; feliz?: number; sonrisa?: number; ojoAlto?: number; lunar?: number; piel?: string; pelo?: string; ropa?: string; op?: number; lunarOn?: boolean; salto?: number}> = ({
  x, y, sc = 1, flip = false, squish = 1, feliz = 0.5, sonrisa = 0, ojoAlto = 0, lunar = 0, piel = '#E8B58F', pelo = '#3A2418', ropa = '#6AA6C9', op = 1, lunarOn = true, salto = 0,
}) => (
  <g transform={`translate(${x} ${y}) scale(${(flip ? -1 : 1) * squish * sc} ${sc})`} opacity={op}>
    {Array.from({length: 15}).map((_, i) => {
      const a = (i / 14) * Math.PI;
      return <circle key={i} cx={-Math.cos(a) * 160} cy={-30 - Math.sin(a) * 175} r={50} fill={pelo} />;
    })}
    <ellipse cx={-150} cy={30} rx={46} ry={90} fill={pelo} />
    <ellipse cx={150} cy={30} rx={46} ry={90} fill={pelo} />
    <ellipse cx={0} cy={330} rx={250} ry={130} fill={ropa} stroke="rgba(0,0,0,0.25)" strokeWidth={5} />
    <rect x={-34} y={140} width={68} height={90} rx={26} fill={piel} />
    <ellipse cx={0} cy={0} rx={138} ry={172} fill={piel} stroke="rgba(0,0,0,0.22)" strokeWidth={5} />
    {Array.from({length: 7}).map((_, i) => <circle key={i} cx={-105 + i * 35} cy={-150 + Math.abs(i - 3) * 14} r={34} fill={pelo} />)}
    {[-1, 1].map((d) => {
      const alto = d === -1 ? ojoAlto : 0;
      return (
        <g key={d}>
          <ellipse cx={d * 52} cy={-20 - alto} rx={27} ry={19} fill="#fff" stroke="#3a2418" strokeWidth={3} />
          <circle cx={d * 52} cy={-20 - alto} r={11} fill="#4a2c18" />
          <circle cx={d * 52 + 4} cy={-24 - alto} r={4} fill="#fff" />
          <path d={`M ${d * 52 - 28} ${-62 - alto + (feliz < 0 ? d * 8 * -feliz : 0)} Q ${d * 52} ${-78 - alto} ${d * 52 + 28} ${-62 - alto - (feliz < 0 ? d * 8 * -feliz : 0)}`} stroke={pelo} strokeWidth={9} fill="none" strokeLinecap="round" />
        </g>
      );
    })}
    <path d="M -6 0 Q -16 28 0 32 Q 16 28 6 0" stroke="#B9805D" strokeWidth={5} fill="none" strokeLinecap="round" />
    <ellipse cx={-92} cy={50} rx={26} ry={15} fill="rgba(255,110,120,0.3)" />
    <ellipse cx={92} cy={50} rx={26} ry={15} fill="rgba(255,110,120,0.3)" />
    <path d={`M -52 ${90 - sonrisa * 2} Q 0 ${90 + feliz * 46} 52 ${90 - sonrisa * 34}`} stroke="#9A3D3D" strokeWidth={9} fill="none" strokeLinecap="round" />
    {lunarOn && (
      <g transform={`translate(-76 ${44 - Math.abs(salto) * 40})`}>
        {lunar > 0 && <circle r={44 * lunar} fill="rgba(231,255,0,0.45)" />}
        <circle r={11} fill="#4A2810" stroke="#2a1608" strokeWidth={2} />
      </g>
    )}
  </g>
);

// teléfono con pantalla recortada
const Telefono: React.FC<{x: number; y: number; sc?: number; rot?: number; children: React.ReactNode; id: string}> = ({x, y, sc = 1, rot = 0, children, id}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc})`}>
    <rect x={-292} y={-562} width={584} height={1124} rx={72} fill="#10151c" stroke="#4b5560" strokeWidth={6} />
    <svg x={-262} y={-532} width={524} height={1064} viewBox="-262 -532 524 1064" overflow="hidden">
      <defs><clipPath id={id}><rect x={-262} y={-532} width={524} height={1064} rx={46} /></clipPath></defs>
      <g clipPath={`url(#${id})`}>{children}</g>
    </svg>
    <rect x={-60} y={-546} width={120} height={22} rx={11} fill="#10151c" />
  </g>
);

const Papelera: React.FC<{x: number; y: number}> = ({x, y}) => (
  <g transform={`translate(${x} ${y})`}>
    <circle r={50} fill="#FFFFFF" opacity={0.85} />
    <rect x={-20} y={-14} width={40} height={42} rx={5} fill="#D6453D" />
    <rect x={-26} y={-24} width={52} height={8} rx={4} fill="#9E2A24" />
    <rect x={-8} y={-32} width={16} height={8} rx={3} fill="#9E2A24" />
  </g>
);

// ---- Sitio 1: la selfie en el celular (E1) ----
const Celu1: React.FC = () => {
  const {s, lin} = useS();
  const dedo = lin(0.1, FOTOS, 0, 1, Easing.inOut(Easing.cubic));
  const fx = 860 + (712 - 860) * dedo, fy = 1300 + (1490 - 1300) * dedo;
  const toc = golpe(s, FOTOS, 30, 6);
  return (
    <AbsoluteFill style={{background: '#7FB5D0'}}>
      <Camara paradas={[{t: 0, x: 540, y: 1000, zoom: 1.0}, {t: FOTOS, x: 540, y: 960, zoom: 1.4}, {t: FOTOS + 1, x: 540, y: 960, zoom: 1.45}]}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 40%, #DDF1FA, #A8D3E6 60%, #5E93B0)" linea="rgba(40,90,120,0.3)" luz="rgba(255,255,255,0.25)" semilla={21} />
        <Lienzo>
          <ellipse cx={560} cy={1700} rx={330} ry={60} fill="rgba(0,0,0,0.25)" />
          <Telefono x={540} y={1030} sc={1.0} rot={Math.sin(s * 1.5) * 1.6} id="cel1">
            <rect x={-262} y={-532} width={524} height={1064} fill="#F5D9C4" />
            <rect x={-262} y={-532} width={524} height={1064} fill="url(#selfG)" />
            <defs><linearGradient id="selfG" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#CFE8F5" /><stop offset="100%" stopColor="#F2D2BD" /></linearGradient></defs>
            <Cara x={0} y={-90} sc={1.35} feliz={-0.7} ojoAlto={0} />
            <rect x={-262} y={420} width={524} height={112} fill="rgba(255,255,255,0.85)" />
            <circle cx={-170} cy={476} r={34} fill="#BFD3E0" />
            <circle cx={0} cy={476} r={40} fill="#fff" stroke="#8aa" strokeWidth={5} />
            <Papelera x={170} y={476} />
          </Telefono>
          {/* manos */}
          <ellipse cx={540} cy={1640} rx={250} ry={70} fill="#E8B58F" stroke="#B9805D" strokeWidth={5} />
          <rect x={800} y={900} width={70} height={190} rx={35} fill="#E8B58F" stroke="#B9805D" strokeWidth={5} />
          <rect x={800} y={1120} width={70} height={190} rx={35} fill="#E8B58F" stroke="#B9805D" strokeWidth={5} />
          {/* dedo que va a borrar */}
          <g transform={`translate(${fx} ${fy}) rotate(-24) scale(${1 - toc * 0.1})`}>
            <rect x={-26} y={-20} width={52} height={230} rx={26} fill="#E8B58F" stroke="#B9805D" strokeWidth={5} />
            <ellipse cx={0} cy={-8} rx={15} ry={10} fill="#F8D8C0" />
          </g>
        </Lienzo>
      </Camara>
    </AbsoluteFill>
  );
};

// ---- Sitio 2: espejo de baño (E2-E5) ----
const PATH: [number, number][] = [[300, 1520], [720, 1340], [320, 1150], [720, 960], [540, 800]];
const Espejo: React.FC = () => {
  const {s, spr, lin} = useS();
  const flipRef = s > DER;
  const squish = s > VOLTEA && s < VOLTEA + 0.6 ? Math.abs(Math.cos(((s - VOLTEA) / 0.6) * Math.PI)) : 1;
  const salto = s > DER ? golpe(s, DER, 20, 5) * 0.6 : 0;
  const luz = interpolate(s, [LUNAR, LUNAR + 0.4], [0, 1], clamp);
  const gran = 1 - interpolate(s, [LLEVAS - 0.4, LLEVAS + 0.1], [0, 1], clamp);
  const oj = interpolate(s, [ALTO - 0.4, ALTO + 0.3], [0, 26], clamp);
  const son = interpolate(s, [SONRISA, SONRISA + 0.5], [0, 1], clamp);
  const flecha = lin(VOLTEA, VOLTEA + 0.45, 0, 1);
  const paradas = [
    {t: TU, x: 540, y: 1000, zoom: 1.0},
    {t: VOLTEA, x: 540, y: 900, zoom: 1.15},
    {t: LUNAR - 0.5, x: 540, y: 880, zoom: 1.2},
    {t: IZQ, x: 540, y: 820, zoom: 2.0},
    {t: DOS - 0.3, x: 540, y: 820, zoom: 1.5},
    {t: DOS, x: 540, y: 790, zoom: 1.35},
    {t: LLEVAS - 0.2, x: 540, y: 790, zoom: 1.2},
    ...seguir(PATH, LLEVAS, CEREBRO - 0.3, 1.1, 5),
    {t: CEREBRO + 1, x: 540, y: 800, zoom: 1.25},
  ];
  const espejitos = PATH.map((p, i) => ({p, t: LLEVAS + 0.3 + i * 0.55}));
  return (
    <AbsoluteFill style={{background: '#8B6B47'}}>
      <Camara paradas={paradas}>
        <Textura tipo="papel" base="radial-gradient(circle at 50% 35%, #FBE6C9, #EBCB9F 60%, #9A7650)" linea="rgba(120,80,40,0.35)" luz="rgba(255,240,215,0.3)" semilla={22} />
        <Lienzo>
          {Array.from({length: 9}).map((_, i) => <line key={'h' + i} x1={0} y1={i * 220} x2={1080} y2={i * 220} stroke="rgba(120,80,40,0.16)" strokeWidth={4} />)}
          {Array.from({length: 8}).map((_, i) => <line key={'v' + i} x1={i * 160} y1={0} x2={i * 160} y2={1920} stroke="rgba(120,80,40,0.16)" strokeWidth={4} />)}
          <rect x={-40} y={1700} width={1160} height={260} fill="#7A5230" />
          <rect x={-40} y={1700} width={1160} height={16} fill="#A67A4C" />
          {/* espejos pequeños: los años de verse al revés */}
          {s > LLEVAS && espejitos.map(({p, t}, i) => {
            const a = spr(t, 12, 130);
            if (a <= 0.01) return null;
            return (
              <g key={i} transform={`translate(${p[0]} ${p[1]}) scale(${a})`}>
                <ellipse rx={150} ry={200} fill="#8B5A2B" />
                <ellipse rx={128} ry={178} fill="url(#vidrioG)" />
                <svg x={-128} y={-178} width={256} height={356} viewBox="-128 -178 256 356" overflow="hidden"><Cara x={0} y={20} sc={0.46} flip /></svg>
                <ellipse cx={-50} cy={-100} rx={14} ry={50} fill="#fff" opacity={0.4} transform="rotate(20)" />
              </g>
            );
          })}
          <defs>
            <radialGradient id="vidrioG" cx="35%" cy="30%" r="80%"><stop offset="0%" stopColor="#F4FBFF" /><stop offset="60%" stopColor="#D3EBF5" /><stop offset="100%" stopColor="#A9CFE0" /></radialGradient>
            <clipPath id="clipEsp"><ellipse cx={540} cy={780} rx={308} ry={398} /></clipPath>
          </defs>
          {/* espejo grande */}
          <g opacity={gran}>
            <ellipse cx={540} cy={780} rx={336} ry={426} fill="#8B5A2B" stroke="#5E3A18" strokeWidth={8} />
            <ellipse cx={540} cy={780} rx={308} ry={398} fill="url(#vidrioG)" />
            <g clipPath="url(#clipEsp)">
              <Cara x={540} y={810} sc={1.0} flip={flipRef} squish={squish} feliz={0.7} ojoAlto={oj} sonrisa={son} lunar={luz} salto={salto} />
              <polygon points="260,420 340,420 620,1180 540,1180" fill="#fff" opacity={0.16} />
            </g>
            <line x1={540} y1={470} x2={540} y2={1130} stroke={LIMA} strokeWidth={5} strokeDasharray="14 12" opacity={interpolate(s, [DOS, DOS + 0.3], [0, 1], clamp)} />
          </g>
          {/* persona real frente al espejo */}
          <g opacity={gran}><Cara x={540} y={1530} sc={0.55} feliz={0.8} lunar={0} /></g>
          {/* flecha curva que gira la imagen */}
          {s > VOLTEA - 0.05 && s < LLEVAS && (
            <g fill="none" stroke={LIMA} strokeWidth={14} strokeLinecap="round">
              <path d="M 840 1290 C 1000 1160 1000 940 840 810" pathLength={1} strokeDasharray={`${flecha} 1`} />
              <path d="M 240 810 C 80 940 80 1160 240 1290" pathLength={1} strokeDasharray={`${flecha} 1`} />
              {flecha > 0.9 && <path d="M 862 836 L 840 810 L 806 826 M 218 1264 L 240 1290 L 274 1274" strokeWidth={12} />}
            </g>
          )}
        </Lienzo>
        {s > ALTO - 0.2 && s < LLEVAS - 0.3 && <Regla x={800} y={745} largo={26} t0={ALTO - 0.2} texto="más alto" vertical color={LIMA} />}
        <Lienzo><Recorrido puntos={PATH} t0={LLEVAS} t1={CEREBRO - 0.3} color="rgba(231,255,0,0.9)" render={(x, y) => <circle cx={x} cy={y} r={14} fill="#4A2810" stroke={LIMA} strokeWidth={5} />} /></Lienzo>
        {s > CEREBRO - 0.1 && (
          <g transform={`translate(540 560) scale(${spr(CEREBRO, 11, 120) * 1.5})`}>
            <svg style={{position: 'absolute', overflow: 'visible'}}><g /></svg>
          </g>
        )}
      </Camara>
      <Chip texto="izquierda" x={270} y={1700} t0={IZQ} t1={DER} color={LIMA} size={60} />
      <Chip texto="derecha" x={810} y={1700} t0={DER} t1={DOS} color={LIMA} size={60} />
      {/* cerebro con corazón lima */}
      {s > CEREBRO - 0.1 && (
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <g transform={`translate(540 640) scale(${spr(CEREBRO, 11, 120) * 1.5})`}>
            <path d="M -120 0 C -150 -70 -90 -120 -30 -100 C 0 -130 70 -120 90 -80 C 150 -90 170 -10 130 30 C 150 80 90 120 40 100 C 10 130 -60 130 -80 90 C -130 100 -150 40 -120 0 Z" fill="#F4A9BE" stroke="#B5546F" strokeWidth={6} />
            <path d="M -40 -90 C -20 -50 -60 -30 -30 0 M 30 -100 C 10 -60 50 -40 20 0 M 80 -60 C 60 -30 100 -10 70 30" stroke="#B5546F" strokeWidth={5} fill="none" strokeLinecap="round" />
            <g transform={`scale(${1 + 0.18 * Math.max(0, Math.sin(s * 9))})`}>
              <path d="M 0 40 C -60 -10 -30 -50 0 -20 C 30 -50 60 -10 0 40 Z" fill={LIMA} stroke="#8a9a00" strokeWidth={4} />
            </g>
          </g>
        </svg>
      )}
    </AbsoluteFill>
  );
};

// ---- Sitio 3: sala de universidad, 1977 (E6-E9) ----
const Mapa: React.FC<{t0: number}> = ({t0}) => {
  const {spr, s} = useS();
  const a = spr(t0, 12, 120);
  if (a <= 0.01) return null;
  return (
    <g transform={`translate(820 520) scale(${a})`}>
      <rect x={-110} y={-130} width={220} height={260} rx={10} fill="#F4EBD3" stroke="#B79F73" strokeWidth={5} />
      <path d="M -50 -80 L -10 -100 L 40 -92 L 56 -66 L 66 -60 L 58 -14 L 66 40 L 52 90 L 6 96 L -20 80 L -26 30 L -42 -20 Z" fill="#CFE6B8" stroke="#4E7A3A" strokeWidth={5} />
      <circle cx={10} cy={10} r={12 + Math.sin(s * 6) * 3} fill="#D6453D" stroke="#7A1D18" strokeWidth={3} />
    </g>
  );
};

const Foto: React.FC<{x: number; y: number; rot: number; flip?: boolean; k: number; marco?: number}> = ({x, y, rot, flip, k, marco = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${k})`}>
    <rect x={-122} y={-142} width={244} height={284} fill="#FFFFFF" stroke="#B9B3A4" strokeWidth={4} />
    <svg x={-105} y={-125} width={210} height={250} viewBox="-105 -125 210 250" overflow="hidden">
      <rect x={-105} y={-125} width={210} height={250} fill="#DCEFF7" />
      <Cara x={0} y={10} sc={0.5} flip={flip} lunar={0} />
    </svg>
    {marco > 0 && <rect x={-136} y={-156} width={272} height={312} fill="none" stroke={LIMA} strokeWidth={12} rx={6} opacity={marco} />}
  </g>
);

const Sala: React.FC = () => {
  const {s, spr, lin} = useS();
  const f1 = lin(IMPRIM, IMPRIM + 0.9, 0, 1, Easing.out(Easing.cubic));
  const f2 = lin(VECES, VECES + 0.9, 0, 1, Easing.out(Easing.cubic));
  const F1 = {x: 540 + (350 - 540) * f1, y: 1010 + (1330 - 1010) * f1, rot: -8 * f1, k: 0.4 + 0.6 * f1};
  const F2 = {x: 540 + (730 - 540) * f2, y: 1010 + (1330 - 1010) * f2, rot: 7 * f2, k: 0.4 + 0.6 * f2};
  const m2 = interpolate(s, [ELIG1, ELIG1 + 0.3, NORMAL2 - 0.1, NORMAL2 + 0.15], [0, 1, 1, 0], clamp);
  const m1 = interpolate(s, [NORMAL2, NORMAL2 + 0.25], [0, 1], clamp);
  const arm = lin(ELIG1, ELIG1 + 0.6, 0, 1);
  const ami = lin(SUS, SUS + 0.9, 0, 1, Easing.out(Easing.cubic));
  const paradas = [
    {t: Y1977 - 0.2, x: 540, y: 760, zoom: 1.9},
    {t: PRUEBA, x: 540, y: 960, zoom: 1.0},
    {t: TOMARON, x: 540, y: 1000, zoom: 1.1},
    {t: VECES + 0.9, x: 540, y: 1240, zoom: 1.25},
    {t: ELIG1 + 0.2, x: 700, y: 1250, zoom: 1.45},
    {t: NORMAL2, x: 400, y: 1250, zoom: 1.45},
    {t: RARA - 0.2, x: 540, y: 1250, zoom: 1.3},
  ];
  return (
    <AbsoluteFill style={{background: '#4A3019'}}>
      <Camara paradas={paradas}>
        <Textura tipo="fibra" base="linear-gradient(180deg, #8A6A44, #5E4023 55%, #3C2813)" linea="rgba(255,220,170,0.22)" luz="rgba(255,235,200,0.2)" semilla={23} />
        <Lienzo>
          {/* pizarra */}
          <rect x={110} y={350} width={860} height={420} rx={14} fill="#1F3A2D" stroke="#8A5A2B" strokeWidth={16} />
          <text x={170} y={470} fontFamily="'Patrick Hand', 'Segoe Print', cursive" fontSize={74} fill="rgba(255,255,255,0.82)">1977</text>
          <path d="M 170 510 L 480 510 M 170 560 L 420 560 M 170 610 L 520 610" stroke="rgba(255,255,255,0.35)" strokeWidth={6} strokeLinecap="round" />
          <Mapa t0={WISC} />
          {/* psicólogos */}
          {s > en('psicólogos') - 0.1 && [[200, 1010], [900, 1010]].map(([px, py], i) => (
            <g key={i} transform={`translate(${px} ${py + (1 - spr(en('psicólogos') + i * 0.15, 12, 110)) * 120})`}>
              <path d="M -100 150 C -100 50 -60 20 0 20 C 60 20 100 50 100 150 Z" fill="#F4F4F4" stroke="#9A9A9A" strokeWidth={4} transform="scale(1.1)" />
              <ellipse cx={0} cy={-20} rx={44} ry={52} fill={i ? '#C99A74' : '#E8B894'} stroke="rgba(0,0,0,0.25)" strokeWidth={3} />
              <path d="M -48 -30 C -52 -90 52 -90 48 -30 C 30 -60 -30 -60 -48 -30 Z" fill={i ? '#555' : '#8A6A3A'} />
              <circle cx={-16} cy={-18} r={13} fill="none" stroke="#222" strokeWidth={4} /><circle cx={16} cy={-18} r={13} fill="none" stroke="#222" strokeWidth={4} />
            </g>
          ))}
          {/* mesa */}
          <rect x={30} y={1250} width={1020} height={420} rx={24} fill="#7A5230" stroke="#4E3219" strokeWidth={8} />
          <rect x={30} y={1250} width={1020} height={26} rx={12} fill="#A67A4C" />
          {/* impresora */}
          <g transform="translate(540 880)">
            <rect x={-210} y={-120} width={420} height={240} rx={22} fill="#C7C0AD" stroke="#7A7464" strokeWidth={7} />
            <rect x={-150} y={-90} width={300} height={40} rx={8} fill="#8B857A" />
            <rect x={-130} y={70} width={260} height={20} rx={6} fill="#3A3730" />
            <circle cx={170} cy={-90} r={12} fill={s > IMPRIM - 0.3 && s < VECES + 1 ? '#6EE070' : '#555'} />
          </g>
          <Foto {...F1} k={f1 > 0.01 ? F1.k : 0} />
          <Foto {...F2} flip k={f2 > 0.01 ? F2.k : 0} />
          {f1 > 0.01 && <Foto x={F1.x} y={F1.y} rot={F1.rot} k={0} />}
          {/* marcos lima */}
          {m2 > 0.01 && <rect x={F2.x - 138} y={F2.y - 158} width={276} height={316} fill="none" stroke={LIMA} strokeWidth={14} rx={8} opacity={m2} />}
          {m1 > 0.01 && <rect x={F1.x - 138} y={F1.y - 158} width={276} height={316} fill="none" stroke={LIMA} strokeWidth={14} rx={8} opacity={m1} />}
          {/* la estudiante toca la foto volteada */}
